import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('melanocytic-naevi',
  kf=["**Melanocytic naevi (moles)** are benign clonal proliferations of melanocytes; most adults have 10–40.",
      "They evolve over life: **junctional** (flat) → **compound** (raised) → **intradermal** (soft, skin-coloured), and many fade after middle age.",
      "Common naevi are symmetrical, one or two colours, under about 6 mm, and match the person's other moles ('signature' naevi).",
      "Dermoscopy patterns (reticular, globular, homogeneous) help; the **ugly duckling** and changing lesion need assessment.",
      "Reassure typical naevi; refer any lesion meeting the NICE 7-point checklist or with clinical concern via the **suspected cancer pathway**."],
  epi=[{"t": "**Who**", "sub": ["Naevi appear in childhood, peak in number in the 20s–30s and decline after 50.", "More naevi with fair skin, childhood sun exposure and family history; acral naevi more common in darker skin."]},
       {"t": "**Melanoma risk**", "sub": ["More than about 100 naevi, or several atypical naevi, is a major melanoma risk factor; most melanomas still arise de novo, not in a pre-existing mole."]}],
  aet=["Somatic **BRAF V600E** (common naevi) or **NRAS** (congenital naevi) mutations start a clone, which then stops growing (oncogene-induced senescence).", "Sun exposure in childhood and genetics (number of naevi is strongly inherited)."],
  myths=["**\"Moles turn into cancer\"**: individual moles rarely do; the number of moles signals risk.", "**\"Hairs mean it's safe\"**: hair does not exclude melanoma."],
  patho_lead="A naevus is a clone of melanocytes that grows, then **switches itself off**.",
  mech=[("Founder mutation", "A melanocyte acquires a **BRAF** or **NRAS** mutation and proliferates as nests at the dermo-epidermal junction (junctional naevus)."),
        ("Senescence", "After a growth phase, the clone enters **oncogene-induced senescence** (p16) and stops enlarging: a stable mole."),
        ("Maturation into the dermis", "Nests drop into the dermis (compound, then intradermal naevus); deeper cells become smaller and less pigmented.", "v3-naevus-life-cycle.jpg", "Life cycle of a naevus: junctional → compound → intradermal, then fading."),
        ("Involution", "Many naevi fade or become fibrous in older age; a new or changing pigmented lesion in an adult needs more caution.")],
  histo=["Junctional: nests at the dermo-epidermal junction; compound: junctional plus dermal nests; intradermal: dermal nests only, showing **maturation** with depth.", "No atypia, symmetry and orderly maturation separate naevi from melanoma."],
  special=[{"t": "**Pregnancy**", "sub": ["Naevi may darken slightly, but a clearly changing mole needs the same assessment as at any other time."]},
           {"t": "**Children**", "sub": ["New naevi are normal; childhood melanoma is rare and often amelanotic or nodular (use modified ABCD criteria)."]}],
  comp=["Irritation, trauma or inflammation (folliculitis within a mole).", "Rarely melanoma arising in a naevus.", "Halo phenomenon (depigmented ring)."],
  prog=["Benign and stable; most change slowly with age. Removal is only for diagnosis or symptoms; cosmetic removal is not NHS-funded."],
  see_also=["melanoma", "atypical-naevus-syndrome", "congenital-melanocytic-naevi", "spitz-blue-halo-naevi", "seborrhoeic-keratosis"])

E('venous-leg-ulcer',
  kf=["**Venous leg ulcers** are the commonest chronic leg ulcers (about 70%), caused by **venous hypertension**.",
      "Gaiter area, especially over the **medial malleolus**; shallow, sloping-edged, exudative ulcer with haemosiderin, venous eczema and lipodermatosclerosis.",
      "Always check **ABPI** before high compression to exclude significant arterial disease.",
      "**Compression** is the cornerstone; plus elevation, walking, wound care and treatment of venous eczema.",
      "Refer if not healing after about 2 weeks of optimal care, atypical, mixed arterial disease or for venous intervention (NICE CG168)."],
  epi=[{"t": "**Who**", "sub": ["Older adults, more women; prevalence rises steeply after 65.", "Risk factors: varicose veins, previous **DVT**, obesity, immobility, multiple pregnancies, leg trauma."]},
       {"t": "**Burden**", "sub": ["Often chronic and recurrent: many recur within a year without ongoing compression."]}],
  aet=["Calf-muscle pump failure (immobility, ankle stiffness, arthritis).", "Post-thrombotic syndrome after DVT."],
  myths=["**\"Swab every ulcer\"**: all chronic ulcers grow bacteria; swab only if clinically infected.", "**\"Compression is unsafe in the elderly\"**: it is safe once ABPI shows adequate arterial supply."],
  patho_lead="Persistently high pressure in the leg veins damages the skin from the inside.",
  mech=[("Valve failure", "Incompetent valves in superficial, perforating or deep veins (often after DVT) let blood **reflux** downwards."),
        ("Venous hypertension", "Walking normally lowers ankle venous pressure; with reflux or pump failure it stays high (**ambulatory venous hypertension**)."),
        ("Capillary leak", "High pressure stretches capillaries; fluid, red cells (later **haemosiderin**) and fibrinogen leak into the tissues, causing oedema and brown staining."),
        ("Inflammation and fibrosis", "White cells trapped in capillaries release enzymes and cytokines; the dermis and fat scar (**lipodermatosclerosis**) and oxygen delivery falls."),
        ("Ulceration", "Minor trauma breaks the fragile skin, which cannot heal while venous pressure stays high: compression reverses this.")],
  histo=["Not needed routinely. **Biopsy** a non-healing or atypical ulcer (rolled edge, exuberant tissue) to exclude SCC (Marjolin ulcer) or BCC."],
  special=[{"t": "**Mixed arterial–venous disease**", "sub": ["ABPI below 0.8 needs reduced or no compression and vascular referral; diabetes can give a falsely high ABPI."]}],
  comp=["Cellulitis; contact allergy to dressings and topical treatments (common in leg ulcer patients).", "Chronic pain, reduced mobility and isolation.", "Malignant change in long-standing ulcers (rare)."],
  prog=["Most heal within months with good compression; recurrence is common, so lifelong compression hosiery is advised after healing."],
  see_also=["arterial-neuropathic-ulcers", "red-leg", "cellulitis-erysipelas", "pyoderma-gangrenosum", "wound-aftercare"])

E('lichen-planus',
  kf=["**Lichen planus** is a T-cell–mediated inflammatory disease of skin, mucosa, hair and nails.",
      "The **6 Ps**: purple, polygonal, planar, pruritic papules and plaques, with white **Wickham striae**; flexor wrists, lower back, ankles.",
      "Check the **mouth**, genitals, nails and scalp; oral LP is often lace-like and white.",
      "Ask about drugs (lichenoid drug eruption) and consider **hepatitis C** testing according to risk.",
      "Potent topical steroids for skin; refer mucosal, nail, scalp (scarring) or extensive disease."],
  epi=[{"t": "**Who**", "sub": ["Adults 30–60; cutaneous LP affects about 1% of people, oral LP 1–2%.", "Rare in children."]},
       {"t": "**Course**", "sub": ["Skin LP usually clears within 1–2 years; oral and genital LP are often chronic."]}],
  aet=["Autoimmune attack on basal keratinocytes, possibly triggered by altered self-antigens (viral, drug).", "Drugs: beta-blockers, ACE inhibitors, thiazides, antimalarials, gold, checkpoint inhibitors."],
  myths=["**\"LP is contagious\"**: it is not.", "**\"Oral LP is just a mouth ulcer\"**: chronic erosive oral LP carries a small risk of SCC and needs follow-up."],
  patho_lead="Cytotoxic T cells attack the **basal layer** of the epidermis (an **interface dermatitis**).",
  mech=[("Antigen on keratinocytes", "An altered antigen on basal keratinocytes is presented to T cells."),
        ("T-cell attack", "CD8+ T cells form a dense **band** along the dermo-epidermal junction and kill basal cells (apoptotic **Civatte bodies**).", "v3-lp-polygonal-koebner.jpg", "Flat-topped violaceous polygonal papules with Wickham striae and a Koebner line."),
        ("Thickened granular layer", "The epidermis responds with a thick granular layer and **saw-tooth** rete ridges: seen clinically as Wickham striae."),
        ("Pigment drop-out", "Melanin falls into the dermis (pigment incontinence), causing long-lasting **post-inflammatory hyperpigmentation**, especially in darker skin."),
        ("Mucosal disease", "In the mouth the same process causes white reticular lace and painful erosions.", "v3-oral-lp-reticular.jpg", "Reticular oral lichen planus on the buccal mucosa.")],
  histo=["Band-like lymphocytic infiltrate at the dermo-epidermal junction, hypergranulosis, saw-tooth acanthosis, Civatte bodies; direct immunofluorescence shows fibrinogen along the basement membrane."],
  special=[{"t": "**Skin of colour**", "sub": ["Papules look grey-brown or purple-black; hyperpigmentation can be the main complaint."]},
           {"t": "**Variants**", "sub": ["Hypertrophic (shins), annular, linear, bullous, actinic, lichen planopilaris (scarring alopecia), nail LP (pterygium)."]}],
  comp=["Post-inflammatory hyperpigmentation.", "Scarring alopecia and permanent nail loss.", "Vulval/penile scarring; small risk of SCC in chronic erosive oral or genital LP."],
  prog=["Cutaneous LP: most resolves in 1–2 years; hypertrophic LP persists longer. Mucosal LP is often lifelong."],
  see_also=["psoriasis", "scarring-alopecia", "nail-signs", "drug-eruption-approach", "contact-lichenoid-pigmentation"])

E('hidradenitis-suppurativa',
  kf=["**Hidradenitis suppurativa (HS)** is a chronic inflammatory disease of the **hair follicle** in the flexures, not an infection of sweat glands.",
      "Recurrent painful nodules, abscesses, sinus tracts and **rope-like scars** in the axillae, groin, buttocks and under the breasts; **double-ended comedones**.",
      "Diagnosis is clinical: typical lesions, typical sites, recurrence (at least twice in 6 months).",
      "Stop smoking, lose weight, analgesia, topical clindamycin 1%, then a **12-week tetracycline course**; screen for metabolic syndrome and depression.",
      "Refer early for Hurley II–III or failed primary care treatment; biologics (adalimumab, secukinumab) are specialist."],
  epi=[{"t": "**Who**", "sub": ["About 1% of people; women about 3× more; starts after puberty, average delay to diagnosis around 7–10 years.", "Strong links with **smoking** and **obesity**; a third have a family history."]}],
  aet=["Follicular occlusion with genetic susceptibility (γ-secretase mutations in familial HS).", "Smoking (nicotine promotes follicular plugging), obesity, friction, hormones."],
  myths=["**\"It's caused by poor hygiene\"**: it is not.", "**\"Repeated incision and drainage cures it\"**: lancing gives brief relief but scars and recurs; treat the disease."],
  patho_lead="HS starts with a **blocked hair follicle** that ruptures and drives chronic inflammation.",
  mech=[("Follicular occlusion", "Hyperkeratosis plugs the hair follicle infundibulum in apocrine-gland–bearing skin."),
        ("Dilation and rupture", "The follicle swells and ruptures, spilling keratin and bacteria into the dermis."),
        ("Inflammatory cascade", "Innate immunity (IL-1β, **TNF-α**, **IL-17**) causes painful nodules and abscesses: the targets of biologic drugs."),
        ("Tunnels and scars", "Repeated inflammation forms epithelialised **sinus tracts**, bridged and **tombstone** comedones, and rope-like scars.", "v3-hs-tombstone-comedones.jpg", "Double-ended (tombstone) comedones and sinus tracts in HS."),
        ("Staging", "Hurley I: abscesses without tracts; II: recurrent abscesses with tracts and scars; III: diffuse interconnected tracts.", "v3-hs-hurley-stages.jpg", "Hurley stages I–III.")],
  histo=["Not needed for diagnosis. Follicular occlusion, perifolliculitis, abscesses and sinus tracts lined by epithelium."],
  special=[{"t": "**Pregnancy and contraception**", "sub": ["Tetracyclines are avoided in pregnancy; specialist advice on alternatives (e.g. clindamycin, some biologics)."]},
           {"t": "**Skin of colour**", "sub": ["More common and often more severe in people of African descent; scarring and keloids."]}],
  comp=["Chronic pain, odour, depression and suicide risk; impaired work and relationships.", "Strictures, lymphoedema, anaemia, fistulae.", "SCC in long-standing buttock or perineal disease (rare); associated Crohn's disease, spondyloarthritis, PCOS."],
  prog=["Chronic, relapsing; early treatment and lifestyle change limit scarring. Surgery (deroofing, excision) for persistent tracts."],
  see_also=["boils-carbuncles", "folliculitis", "acne-vulgaris", "intertrigo", "biologics-systemics"])

E('alopecia-areata',
  kf=["**Alopecia areata** is autoimmune, **non-scarring** hair loss in round or oval patches with normal-looking skin.",
      "**Exclamation-mark hairs** at the edge; can affect beard, brows, lashes and nails (pitting).",
      "Severe forms: **ophiasis** (band along the hairline), totalis (whole scalp) and universalis (all body hair).",
      "About 80% of small, short-duration patches regrow within a year, but relapse is common.",
      "Adults: potent or very potent scalp steroid for about 3 months (off-label); refer children, extensive or distressing disease (JAK inhibitors are specialist)."],
  epi=[{"t": "**Who**", "sub": ["Lifetime risk about 2%; any age, often starting in childhood or young adulthood.", "Associated with atopy, thyroid disease, vitiligo and Down syndrome."]}],
  aet=["Loss of the hair follicle's **immune privilege** with CD8+ T-cell attack; genetic susceptibility (HLA, ULBP3).", "Triggers sometimes reported: stress, illness."],
  myths=["**\"Stress alone causes it\"**: it is autoimmune; stress may trigger flares.", "**\"Hair loss is permanent\"**: follicles are not destroyed, so regrowth is possible even after years."],
  patho_lead="Immune cells attack **growing (anagen) hair bulbs** but spare the stem cells, so hair can regrow.",
  mech=[("Immune privilege collapse", "Anagen bulbs normally hide their antigens (low MHC class I); in AA this privilege fails."),
        ("T-cell attack", "Interferon-γ and **JAK–STAT** signalling recruit CD8+ T cells around the bulb ('swarm of bees'): the target of JAK inhibitors."),
        ("Dystrophic hairs", "Damaged hairs narrow near the scalp and break: **exclamation-mark hairs**; follicles enter early catagen and telogen."),
        ("Regrowth", "Stem cells in the bulge survive, so regrowth often starts as fine white hairs that later repigment.")],
  histo=["Peribulbar lymphocytic infiltrate around anagen follicles; increased catagen/telogen hairs; no scarring. Biopsy only if the diagnosis is uncertain."],
  special=[{"t": "**Children**", "sub": ["Refer; use lower-potency steroids, and consider the psychosocial impact and school support."]},
           {"t": "**Nails**", "sub": ["Fine regular pitting or trachyonychia in 10–20%, more with severe disease."]}],
  comp=["Anxiety, depression and social withdrawal.", "Loss of eyelashes and brows (eye irritation).", "Associated autoimmune disease."],
  prog=["Unpredictable. Worse outlook: onset in childhood, extensive or ophiasis pattern, nail disease, atopy, long duration."],
  see_also=["androgenetic-alopecia", "telogen-effluvium", "trichotillomania", "scarring-alopecia", "tinea"])

E('androgenetic-alopecia',
  kf=["**Androgenetic alopecia** (male- and female-pattern hair loss) is the commonest cause of hair loss: genetic sensitivity of follicles to androgens.",
      "Men: temporal recession and vertex thinning (Hamilton–Norwood); women: diffuse crown thinning with a **preserved frontal hairline** and widened parting (Ludwig).",
      "Hallmark: **miniaturisation** (hairs of varying thickness).",
      "Topical **minoxidil** 2% or 5% for both sexes (continuous, about 6 months to judge); **finasteride 1 mg** in men.",
      "In women with signs of hyperandrogenism (acne, hirsutism, irregular periods) check for PCOS or another cause."],
  epi=[{"t": "**Who**", "sub": ["About half of men by 50 and up to 40% of women by 70.", "Strong family history; onset after puberty."]}],
  aet=["Polygenic inheritance (androgen receptor gene on the X chromosome and others).", "**Dihydrotestosterone (DHT)** formed by 5α-reductase in the scalp."],
  myths=["**\"Hats or frequent washing cause baldness\"**: they do not.", "**\"Minoxidil can be stopped once hair returns\"**: stopping loses the gains within months."],
  patho_lead="DHT gradually **shrinks** genetically susceptible scalp follicles.",
  mech=[("Androgen activation", "5α-reductase type II converts testosterone to **DHT** in the follicle; finasteride blocks this step."),
        ("Shorter anagen", "DHT shortens each growth phase, so hairs grow for less time and are shorter."),
        ("Miniaturisation", "Each cycle produces a thinner, shorter, less pigmented hair until terminal hairs become vellus-like."),
        ("Visible thinning", "More follicles in telogen and fewer terminal hairs give see-through scalp in a patterned distribution.")],
  histo=["Rarely needed: reduced terminal-to-vellus ratio, increased telogen hairs, no scarring. Dermoscopy shows variable hair diameter (anisotrichosis)."],
  special=[{"t": "**Women**", "sub": ["Usually normal androgen levels; test only if there are features of hyperandrogenism.", "Spironolactone is an off-label specialist option; contraception needed."]}],
  comp=["Psychological distress; sunburn and actinic damage on the bald scalp."],
  prog=["Slowly progressive; treatment stabilises or partly reverses loss while it continues."],
  see_also=["telogen-effluvium", "alopecia-areata", "hirsutism", "scarring-alopecia"])

E('telogen-effluvium',
  kf=["**Telogen effluvium** is diffuse shedding about **2–3 months after a trigger**, when many follicles shift into telogen together.",
      "Triggers: childbirth, febrile illness (including COVID-19), surgery, crash diets, iron deficiency, thyroid disease, new drugs.",
      "Positive **hair-pull test** (more than 4–6 club hairs) in the acute phase; no scarring, no miniaturisation.",
      "Check ferritin, thyroid function and full blood count if the trigger is unclear.",
      "Reassure: regrowth over **6–12 months** once the trigger has gone; chronic TE lasts longer than 6 months."],
  epi=[{"t": "**Who**", "sub": ["Common at any age, more often reported by women.", "Postpartum shedding affects many women 2–4 months after delivery."]}],
  aet=["Physiological stress, hormonal change, nutritional deficiency or drugs (retinoids, anticoagulants, beta-blockers, stopping the combined pill)."],
  myths=["**\"Shedding means I'll go bald\"**: follicles are alive and will regrow.", "**\"Hair supplements cure it\"**: only replace a proven deficiency."],
  patho_lead="A shock **synchronises** hair cycles so many hairs rest and then fall together.",
  mech=[("Normal cycle", "Normally about 85–90% of scalp hairs are growing (anagen) and 10–15% resting (telogen) at any time."),
        ("Trigger", "A physiological shock pushes many anagen follicles into early **telogen** at once."),
        ("Delayed shedding", "Telogen lasts about 3 months, so club hairs shed in large numbers 2–3 months after the trigger."),
        ("Recovery", "New anagen hairs push out the old ones; short regrowing hairs at the hairline are a good sign.")],
  histo=["Biopsy only if unclear: normal follicle numbers with an increased proportion of telogen follicles; no miniaturisation or inflammation."],
  special=[{"t": "**Postpartum**", "sub": ["Shedding peaks 3–4 months after delivery and usually settles by 12 months."]}],
  comp=["Anxiety; may unmask underlying androgenetic alopecia."],
  prog=["Acute TE resolves in most within 6–12 months; chronic TE fluctuates over years but rarely causes baldness."],
  see_also=["androgenetic-alopecia", "alopecia-areata", "trichotillomania"])

E('itch-xerosis-older-adults',
  kf=["**Xerosis** (dry skin) is the commonest cause of itch in older adults; asteatotic eczema (*eczema craquelé*) is its inflamed form, especially on the shins.",
      "Look for a cause of itch without rash: iron deficiency, renal or liver disease, thyroid disease, haematological malignancy, drugs.",
      "Cornerstone: emollients **liberally and often** (2–3 times a day and after washing), soap substitutes, short lukewarm showers.",
      "Short course of a moderately potent steroid for asteatotic flares; warn about **fire risk** of emollient-soaked fabric and slippery floors.",
      "Do not forget scabies, bullous pemphigoid (prodrome) and drug reactions in itchy older people."],
  epi=[{"t": "**Who**", "sub": ["Most people over 65 have some xerosis; worse in winter, with central heating and frequent washing."]}],
  aet=["Ageing skin: less lipid and filaggrin, slower barrier repair, reduced sweat and sebum.", "Diuretics, statins and other drugs; hypothyroidism; low humidity."],
  myths=["**\"Itching in older people is just age\"**: always examine for scabies, pemphigoid and systemic causes.", "**\"Antihistamines help dry-skin itch\"**: sedating ones cause falls and confusion and do little for xerotic itch."],
  patho_lead="Ageing skin loses its **lipid barrier**, lets water escape and becomes itchy and cracked.",
  mech=[("Barrier lipid loss", "Ceramides, cholesterol and natural moisturising factor fall with age.", "v3-eczema-barrier-section.jpg", "A leaky skin barrier lets water out and irritants in."),
        ("Water loss and scaling", "Transepidermal water loss rises; corneocytes shrink and scale."),
        ("Cracking", "Fine fissures form a 'crazy-paving' pattern on the shins (eczema craquelé).", "v3-asteatotic-shins.jpg", "Asteatotic eczema: crazy-paving pattern on the shins."),
        ("Itch–scratch cycle", "Nerve fibres in dry skin become sensitised; scratching damages the barrier further."),
        ("Repair", "Regular emollient restores lipids and breaks the cycle.", "v3-older-leg-applicator.jpg", "A long-handled applicator helps older people apply emollient to the legs.")],
  special=[{"t": "**Itch without rash (generalised pruritus)**", "sub": ["Check FBC, ferritin, U&E, LFT, TFT, HbA1c; consider chest X-ray if there are systemic symptoms."]}],
  comp=["Infected eczema; skin tears and dermatoporosis.", "Sleep disturbance, depression.", "Falls from slippery emollients; burns from emollient-soaked fabrics."],
  prog=["Chronic and seasonal; controlled with daily skin care."],
  see_also=["eczema-dermatitis", "emollients", "skin-fragility-dermatoporosis", "bullous-pemphigoid", "scabies"])
